import React, { useState, useEffect } from 'react';
import { useParams, useNavigate, Link } from 'react-router-dom';
import { getProperty, sendEnquiry } from '../services/api';
import { useSaved } from '../context/SavedContext';
import { useAuth } from '../context/AuthContext';
import Logo from '../components/Logo';
import {
  Heart, MapPin, CheckCircle, ArrowLeft,
  ChevronDown, ChevronUp, Phone, Check,
  Camera, Video, Compass, Download, Share2, Star
} from 'lucide-react';
import styles from './PropertyDetailPage.module.css';

/* ── Tab definitions matching screenshot ─────────────────── */
const TABS = [
  { id: 'overview',     label: 'OVERVIEW' },
  { id: 'gallery',      label: 'GALLERY' },
  { id: 'highlights',   label: 'HIGHLIGHTS' },
  { id: 'about',        label: 'ABOUT' },
  { id: 'amenities',    label: 'AMENITIES' },
  { id: 'location',     label: 'LOCATION MAP' },
  { id: 'builder',      label: 'BUILDER' },
  { id: 'faq',          label: 'FAQ' },
];

export default function PropertyDetailPage() {
  const { id } = useParams();
  const navigate = useNavigate();
  const { user } = useAuth();
  const { isSaved, toggle } = useSaved();

  const [property,     setProperty]     = useState(null);
  const [loading,      setLoading]      = useState(true);
  const [activeTab,    setActiveTab]    = useState('overview');
  const [activeImg,    setActiveImg]    = useState(0);

  /* Form state */
  const [leadName,     setLeadName]     = useState('');
  const [leadPhone,    setLeadPhone]    = useState('');
  const [leadEmail,    setLeadEmail]    = useState('');
  const [sending,      setSending]      = useState(false);
  const [submitted,    setSubmitted]    = useState(false);
  const [errorMsg,     setErrorMsg]     = useState('');

  /* FAQ Accordion state */
  const [openFaq,      setOpenFaq]      = useState(0);

  useEffect(() => {
    getProperty(id)
      .then(({ data }) => {
        setProperty(data.property);
        if (data.property) {
          window.scrollTo({ top: 0, behavior: 'smooth' });
        }
      })
      .catch(() => navigate('/'))
      .finally(() => setLoading(false));
  }, [id, navigate]);

  // Pre-fill user info if logged in
  useEffect(() => {
    if (user) {
      setLeadName(user.name || '');
      setLeadPhone(user.phone || '');
      setLeadEmail(user.email || '');
    }
  }, [user]);

  if (loading) {
    return (
      <div className={styles.loadingWrap}>
        <div className={styles.spinner} />
        <p>Loading property details...</p>
      </div>
    );
  }

  if (!property) return null;

  const p = property;
  const images = [p.image, ...(p.images || [])].filter(Boolean);
  const saved = isSaved(p.id || p._id);

  const handleSave = () => {
    if (!user) {
      navigate('/login');
      return;
    }
    toggle(p);
  };

  /* Scroll to section on tab click */
  const handleTabClick = (tabId) => {
    setActiveTab(tabId);
    const el = document.getElementById(tabId);
    if (el) {
      const yOffset = -130;
      const y = el.getBoundingClientRect().top + window.pageYOffset + yOffset;
      window.scrollTo({ top: y, behavior: 'smooth' });
    }
  };

  /* Contact Seller submission */
  const handleContactSubmit = async (e) => {
    e.preventDefault();
    setErrorMsg('');

    if (!leadPhone.trim()) {
      setErrorMsg('Please enter your mobile number.');
      return;
    }

    setSending(true);
    try {
      await sendEnquiry({
        propertyId: p.id || p._id,
        name: leadName || 'Interested Buyer',
        phone: leadPhone,
        email: leadEmail,
        message: `Interested in callback for ${p.title} (${p.location})`,
      });
      setSubmitted(true);
    } catch (err) {
      setErrorMsg(err.response?.data?.message || 'Failed to submit enquiry. Please try again.');
    } finally {
      setSending(false);
    }
  };

  /* Native Share or Social fallback */
  const shareUrl = window.location.href;
  const shareTitle = `${p.title} in ${p.location} | Probridge`;

  const handleShareClick = async () => {
    if (navigator.share) {
      try {
        await navigator.share({ title: shareTitle, url: shareUrl });
      } catch {}
    } else {
      navigator.clipboard?.writeText(shareUrl);
      alert('Link copied to clipboard!');
    }
  };

  const shareLinks = {
    linkedin: `https://www.linkedin.com/sharing/share-offsite/?url=${encodeURIComponent(shareUrl)}`,
    twitter:  `https://twitter.com/intent/tweet?text=${encodeURIComponent(shareTitle)}&url=${encodeURIComponent(shareUrl)}`,
    whatsapp: `https://api.whatsapp.com/send?text=${encodeURIComponent(shareTitle + ' ' + shareUrl)}`,
    facebook: `https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(shareUrl)}`,
    gmail:    `mailto:?subject=${encodeURIComponent(shareTitle)}&body=${encodeURIComponent('Check out this property on Probridge: ' + shareUrl)}`,
  };

  const highlights = [
    `Located in prime ${p.locality || p.location || p.city || 'residential'} suburb`,
    `Well-connected to arterial roads, transit corridors & business hubs`,
    p.bedroom ? `Spacious ${p.bedroom.includes('BHK') ? p.bedroom : p.bedroom + ' BHK'} modern configuration options` : 'Spacious multi-family modern layout options',
    `Gated community with 24×7 multi-tier security and CCTV surveillance`,
    `Modern architecture with maximum natural ventilation & sunlight`,
    p.possession ? `Possession status: ${p.possession}` : 'Ready for occupancy with verified clear titles',
  ];

  const faqs = [
    {
      q: `What is the possession date for ${p.title}?`,
      a: `The property is currently marked as ${p.possession || 'Ready to Move'}. Contact the seller for the exact key-handover timeline.`,
    },
    {
      q: `Are bank home loans available for this property?`,
      a: `Yes, home loans are pre-approved by leading financial institutions including SBI, HDFC Bank, ICICI Bank, and Axis Bank.`,
    },
    {
      q: `Is the project RERA approved?`,
      a: `Yes, this property has verified title documentation and compliance approvals from the local planning authority and RERA.`,
    },
    {
      q: `What amenities are included in the community?`,
      a: p.amenities?.length > 0
        ? `Amenities include ${p.amenities.slice(0, 5).join(', ')} and more.`
        : 'Amenities include 24x7 security, water supply, power backup, lift, and dedicated parking.',
    },
  ];

  return (
    <div className={styles.pageWrap}>

      {/* ── FIXED DUAL NAVBAR (Back Listing Navbar + Sub Tabs Navbar stay sticky together on scroll) ── */}
      <div className={styles.stickyHeaderWrapper}>

        {/* Row 1: "Back to listings" Navbar */}
        <div className={styles.topBackNav}>
          <div className={`container ${styles.topBackInner}`}>
            <div className={styles.leftNavGroup}>
              <button className={styles.backBtn} onClick={() => navigate(-1)}>
                <ArrowLeft size={16} />
                <span>Back to listings</span>
              </button>

              <span className={styles.navDivider}>|</span>

              <nav className={styles.breadcrumb}>
                <Link to="/">Home</Link>
                <span>›</span>
                {p.city && (
                  <>
                    <Link to={`/search?city=${encodeURIComponent(p.city)}`}>Properties in {p.city}</Link>
                    <span>›</span>
                  </>
                )}
                {p.locality && (
                  <>
                    <Link to={`/search?city=${encodeURIComponent(p.city)}&q=${encodeURIComponent(p.locality)}`}>
                      {p.locality}
                    </Link>
                    <span>›</span>
                  </>
                )}
                <span className={styles.currentCrumb}>{p.title}</span>
              </nav>
            </div>

            <div className={styles.rightNavGroup}>
              <Link to="/" className={styles.brandLink}>
                <Logo size="sm" showTagline={false} />
              </Link>
            </div>
          </div>
        </div>

        {/* Row 2: Sub-Navigation Tabs Bar */}
        <nav className={styles.subTabsNav}>
          <div className={`container ${styles.tabList}`}>
            {TABS.map((tab) => (
              <button
                key={tab.id}
                type="button"
                className={`${styles.tabBtn} ${activeTab === tab.id ? styles.tabBtnActive : ''}`}
                onClick={() => handleTabClick(tab.id)}
              >
                {tab.label}
              </button>
            ))}
          </div>
        </nav>
      </div>

      {/* ── Main Content Container ── */}
      <div className={`container ${styles.mainContent}`}>

        {/* ── 1. HERO IMAGE SECTION (Neatly styled exactly like uploaded screenshot) ── */}
        <div className={styles.heroImageSection}>
          <div className={styles.imageCard}>
            <img
              src={images[activeImg] || 'https://images.unsplash.com/photo-1600585154340-be6161a56a0c?w=1200&q=85'}
              alt={p.title}
              className={styles.heroImg}
            />

            {/* Top-Right Action Badges (Heart + Share) */}
            <div className={styles.imageTopActions}>
              <button
                type="button"
                className={`${styles.imageHeartBtn} ${saved ? styles.imageHeartBtnActive : ''}`}
                onClick={handleSave}
                title={saved ? 'Remove from Saved' : 'Save Property'}
              >
                <Heart size={18} fill={saved ? '#FFFFFF' : 'none'} color="#FFFFFF" />
              </button>

              <button
                type="button"
                className={styles.imageShareBtn}
                onClick={handleShareClick}
                title="Share Property"
              >
                <Share2 size={18} color="#0F172A" />
              </button>
            </div>

            {/* Bottom Floating Pill Buttons (Photos, Videos, Map, Brochure) */}
            <div className={styles.imageBottomPills}>
              <button
                type="button"
                className={styles.pillBtn}
                onClick={() => handleTabClick('gallery')}
              >
                <Camera size={15} />
                <span>{images.length || 1} Photos</span>
              </button>

              <button
                type="button"
                className={styles.pillBtn}
                onClick={() => alert('Virtual video tour available upon request.')}
              >
                <Video size={15} />
                <span>Videos</span>
              </button>

              <button
                type="button"
                className={styles.pillBtn}
                onClick={() => handleTabClick('location')}
              >
                <Compass size={15} />
                <span>Map</span>
              </button>

              <button
                type="button"
                className={styles.pillBtn}
                onClick={() => {
                  const target = document.getElementById('callbackCard');
                  if (target) {
                    target.scrollIntoView({ behavior: 'smooth' });
                  }
                }}
              >
                <Download size={15} />
                <span>Request Brochure</span>
              </button>
            </div>
          </div>
        </div>

        {/* ── 2. PROPERTY TITLE, PRICE & SPECS CARD (Matching screenshot) ── */}
        <div className={styles.propertyHeaderCard}>
          <div className={styles.headerLeft}>
            <h1 className={styles.propertyTitle}>{p.title}</h1>
            <div className={styles.propertyLoc}>
              <MapPin size={16} className={styles.locPin} />
              <span>{p.location || `${p.locality ? p.locality + ', ' : ''}${p.city || 'India'}`}</span>
            </div>
            <div className={styles.propertyMeta}>
              <span>By: <strong>{p.ownerName || 'VGK Builders & Promoters'}</strong></span>
              <span className={styles.metaDot}>•</span>
              <span>Status: <strong className={styles.statusVal}>{p.possession || 'Under Construction'}</strong></span>
            </div>
          </div>

          <div className={styles.headerRight}>
            <div className={styles.priceRow}>
              <span className={styles.priceValue}>{p.price}</span>
            </div>
            <div className={styles.updatedDate}>
              Updated on: {new Date(p.updatedAt || Date.now()).toLocaleDateString('en-US', { day: 'numeric', month: 'long', year: 'numeric' })}
            </div>
            <div className={styles.ratingBadge}>
              <Star size={14} fill="#F59E0B" color="#F59E0B" />
              <span className={styles.ratingNum}>4.1</span>
              <span className={styles.ratingCount}>(7 Ratings)</span>
            </div>
          </div>
        </div>

        {/* ── 3. TWO-COLUMN DETAILS LAYOUT ── */}
        <div className={styles.twoColLayout}>

          {/* Left Column (Overview, Highlights, About, Gallery, Amenities, Map, Builder, FAQ) */}
          <div className={styles.leftCol}>

            {/* CARD 1: Property Overview */}
            <section id="overview" className={styles.card}>
              <h2 className={styles.cardTitle}>{p.title} Overview</h2>

              <div className={styles.overviewGrid}>
                <div className={styles.overviewItem}>
                  <span className={styles.itemLabel}>Apartments</span>
                  <span className={styles.itemValue}>
                    {p.bedroom ? (p.bedroom.includes('BHK') ? p.bedroom : `${p.bedroom} BHK`) : '2 , 3 BHK'}
                  </span>
                </div>

                <div className={styles.overviewItem}>
                  <span className={styles.itemLabel}>Area (Super Build Up)</span>
                  <span className={styles.itemValue}>
                    {p.area || p.plotSize || '947–1423 sq.ft'}
                  </span>
                </div>

                <div className={styles.overviewItem}>
                  <span className={styles.itemLabel}>Total Area</span>
                  <span className={styles.itemValue}>
                    {p.plotSize || '1.8 Acres'}
                  </span>
                </div>

                <div className={styles.overviewItem}>
                  <span className={styles.itemLabel}>Possession Date</span>
                  <span className={styles.itemValue}>
                    {p.possession || 'May-2030'}
                  </span>
                </div>

                <div className={styles.overviewItemWide}>
                  <span className={styles.itemLabel}>PROJECT RERA ID</span>
                  <span className={styles.itemValue}>
                    TN/29/Building/{Math.abs((p.title.length * 37) % 899 + 100)}/2022
                  </span>
                </div>
              </div>
            </section>

            {/* CARD 2: Highlights */}
            <section id="highlights" className={styles.card}>
              <h2 className={styles.cardTitle}>{p.title} Highlights</h2>
              <ul className={styles.highlightsList}>
                {highlights.map((h, i) => (
                  <li key={i} className={styles.highlightItem}>
                    <span className={styles.bulletPoint}>•</span>
                    <span>{h}</span>
                  </li>
                ))}
              </ul>
            </section>

            {/* CARD 3: About Property */}
            <section id="about" className={styles.card}>
              <h2 className={styles.cardTitle}>About {p.title}</h2>
              <div className={styles.aboutText}>
                <p>
                  {p.description ||
                    `${p.title} is an exceptional residential landmark offering sophisticated modern living spaces in prime ${p.location || p.city}. Thoughtfully designed to prioritize abundant natural ventilation, expansive layouts, and contemporary aesthetics.`}
                </p>
                <p>
                  Situated near leading IT hubs, schools, and health infrastructure, ensuring optimal daily convenience and strong long-term appreciation potential.
                </p>
              </div>
            </section>

            {/* CARD 4: Gallery */}
            <section id="gallery" className={styles.card}>
              <h2 className={styles.cardTitle}>{p.title} Gallery</h2>
              <div className={styles.galleryWrapper}>
                <div className={styles.mainImgHolder}>
                  <img
                    src={images[activeImg] || 'https://images.unsplash.com/photo-1600585154340-be6161a56a0c?w=1000&q=80'}
                    alt={p.title}
                    className={styles.mainImage}
                  />
                  <div className={styles.verifiedTag}>
                    <CheckCircle size={14} />
                    <span>Verified Project</span>
                  </div>
                </div>

                {images.length > 1 && (
                  <div className={styles.thumbStrip}>
                    {images.map((img, idx) => (
                      <img
                        key={idx}
                        src={img}
                        alt={`Slide ${idx + 1}`}
                        className={`${styles.thumbImg} ${idx === activeImg ? styles.thumbImgActive : ''}`}
                        onClick={() => setActiveImg(idx)}
                      />
                    ))}
                  </div>
                )}
              </div>
            </section>

            {/* CARD 5: Amenities */}
            <section id="amenities" className={styles.card}>
              <h2 className={styles.cardTitle}>Amenities & Features</h2>
              <div className={styles.amenitiesGrid}>
                {(p.amenities?.length > 0
                  ? p.amenities
                  : ['Covered Parking', 'Swimming Pool', 'Gymnasium', 'High Speed Lift', '24x7 Security', 'Landscaped Garden', 'Clubhouse', 'Power Backup', 'CCTV Surveillance']
                ).map((amenity, idx) => (
                  <div key={idx} className={styles.amenityCard}>
                    <Check size={16} className={styles.amenityCheck} />
                    <span>{amenity}</span>
                  </div>
                ))}
              </div>
            </section>

            {/* CARD 6: Location & Connectivity */}
            <section id="location" className={styles.card}>
              <h2 className={styles.cardTitle}>Location Map & Landmarks</h2>
              <div className={styles.locationBox}>
                <MapPin size={22} className={styles.locPinIcon} />
                <div>
                  <h4 className={styles.locAddress}>{p.location}</h4>
                  <p className={styles.locSub}>{p.city || 'Tamil Nadu'}, India</p>
                </div>
              </div>
              <div className={styles.landmarksGrid}>
                <div className={styles.landmarkItem}>
                  <span className={styles.landmarkIcon}>✈️</span>
                  <div>
                    <strong>Airport / Transit</strong>
                    <p>Approx 25 mins drive</p>
                  </div>
                </div>
                <div className={styles.landmarkItem}>
                  <span className={styles.landmarkIcon}>🚆</span>
                  <div>
                    <strong>Metro / Railway Station</strong>
                    <p>Approx 10 mins drive</p>
                  </div>
                </div>
                <div className={styles.landmarkItem}>
                  <span className={styles.landmarkIcon}>🏥</span>
                  <div>
                    <strong>Hospitals & Healthcare</strong>
                    <p>Within 3-5 km radius</p>
                  </div>
                </div>
                <div className={styles.landmarkItem}>
                  <span className={styles.landmarkIcon}>🎓</span>
                  <div>
                    <strong>Schools & Colleges</strong>
                    <p>Reputed institutions nearby</p>
                  </div>
                </div>
              </div>
            </section>

            {/* CARD 7: Builder / Developer Details */}
            <section id="builder" className={styles.card}>
              <h2 className={styles.cardTitle}>Builder / Developer Details</h2>
              <div className={styles.builderProfile}>
                <div className={styles.builderAvatar}>
                  {(p.ownerName || 'V')[0]?.toUpperCase()}
                </div>
                <div className={styles.builderInfo}>
                  <h3 className={styles.builderName}>{p.ownerName || 'VGK Builders'}</h3>
                  <span className={styles.builderRole}>{p.userType || 'Verified Developer'}</span>
                  {p.ownerPhone && (
                    <p className={styles.builderPhone}>
                      <Phone size={14} /> {p.ownerPhone}
                    </p>
                  )}
                </div>
              </div>
            </section>

            {/* CARD 8: Frequently Asked Questions */}
            <section id="faq" className={styles.card}>
              <h2 className={styles.cardTitle}>Frequently Asked Questions</h2>
              <div className={styles.faqList}>
                {faqs.map((f, idx) => (
                  <div key={idx} className={styles.faqItem}>
                    <button
                      type="button"
                      className={styles.faqQuestion}
                      onClick={() => setOpenFaq(openFaq === idx ? -1 : idx)}
                    >
                      <span>{f.q}</span>
                      {openFaq === idx ? <ChevronUp size={18} /> : <ChevronDown size={18} />}
                    </button>
                    {openFaq === idx && (
                      <div className={styles.faqAnswer}>
                        <p>{f.a}</p>
                      </div>
                    )}
                  </div>
                ))}
              </div>
            </section>

          </div>

          {/* Right Column (Sticky Callback Form + Social Share) */}
          <div className={styles.rightCol}>

            {/* STICKY CARD: Are you interested in This Property? */}
            <div id="callbackCard" className={styles.interestCard}>
              <h3 className={styles.interestTitle}>Are you interested in This Property?</h3>
              <p className={styles.interestSub}>Request a Callback</p>

              {submitted ? (
                <div className={styles.successBox}>
                  <CheckCircle size={36} color="#134E3A" />
                  <h4>Callback Requested!</h4>
                  <p>Our property advisor will get in touch with you shortly.</p>
                  <button
                    type="button"
                    className={styles.resetBtn}
                    onClick={() => setSubmitted(false)}
                  >
                    Request Another
                  </button>
                </div>
              ) : (
                <form onSubmit={handleContactSubmit} className={styles.callbackForm}>
                  {errorMsg && <div className={styles.errorAlert}>{errorMsg}</div>}

                  <div className={styles.inputGroup}>
                    <input
                      type="text"
                      className={styles.textInput}
                      placeholder="Name"
                      value={leadName}
                      onChange={(e) => setLeadName(e.target.value)}
                    />
                  </div>

                  <div className={styles.inputGroup}>
                    <input
                      type="tel"
                      className={styles.textInput}
                      placeholder="Mobile Number"
                      value={leadPhone}
                      onChange={(e) => setLeadPhone(e.target.value)}
                      required
                    />
                  </div>

                  <div className={styles.inputGroup}>
                    <input
                      type="email"
                      className={styles.textInput}
                      placeholder="Email ID (Optional)"
                      value={leadEmail}
                      onChange={(e) => setLeadEmail(e.target.value)}
                    />
                  </div>

                  {/* Forest Green Contact Seller button */}
                  <button
                    type="submit"
                    disabled={sending}
                    className={styles.contactSellerBtn}
                  >
                    {sending ? 'Submitting...' : 'Contact Seller'}
                  </button>
                </form>
              )}
            </div>

            {/* SHARE THIS PROPERTY CARD */}
            <div className={styles.shareCard}>
              <h4 className={styles.shareTitle}>Share This Property</h4>
              <div className={styles.socialRow}>
                <a
                  href={shareLinks.linkedin}
                  target="_blank"
                  rel="noopener noreferrer"
                  className={`${styles.socialBtn} ${styles.socialLinkedin}`}
                  title="Share on LinkedIn"
                >
                  in
                </a>

                <a
                  href={shareLinks.twitter}
                  target="_blank"
                  rel="noopener noreferrer"
                  className={`${styles.socialBtn} ${styles.socialTwitter}`}
                  title="Share on X"
                >
                  𝕏
                </a>

                <a
                  href={shareLinks.whatsapp}
                  target="_blank"
                  rel="noopener noreferrer"
                  className={`${styles.socialBtn} ${styles.socialWhatsapp}`}
                  title="Share on WhatsApp"
                >
                  ✆
                </a>

                <a
                  href={shareLinks.facebook}
                  target="_blank"
                  rel="noopener noreferrer"
                  className={`${styles.socialBtn} ${styles.socialFacebook}`}
                  title="Share on Facebook"
                >
                  f
                </a>

                <a
                  href={shareLinks.gmail}
                  className={`${styles.socialBtn} ${styles.socialGmail}`}
                  title="Share via Email"
                >
                  M
                </a>
              </div>
            </div>

          </div>

        </div>

      </div>

    </div>
  );
}
